+    return llvm::isa<RankedTensorType>(operand.getType());
+  });
+  bool allResultsTensor = llvm::all_of(op->getResults(), [](Value result) {
+    return llvm::isa<RankedTensorType>(result.getType());
+  });
+  return allOperandsTensor && allResultsTensor;
