+
+static bool isFillEliminableByInlineBrc(linalg::FillOp fillOp) {
+  if (fillOp->getNumResults() != 1 || fillOp.getInputs().size() != 1 ||
+      !fillOp.getInputs().front().getType().isIntOrFloat() ||
+      !isa<RankedTensorType>(fillOp->getResult(0).getType())) {
+    return false;
+  }
