+    registry.insert<hivm::HIVMDialect>();
+  }
+  void runOnOperation() override {
+    tcbReuse::protectTcbReuse(getOperation(), "store tcb reuse",
+                              hivm::PIPE::PIPE_MTE3,
+                              hasTwoStoresAfterMainLoops);
+  }
+};
